bool TAIAdying::act(Teki& teki)
{
	if (teki.animationFinished()) {
		switch (teki.mTekiType) {
		case TEKI_Mar:
		{
			teki.clearTekiOption(BTeki::TEKI_OPTION_SHADOW_VISIBLE);
			// fallthrough
		}
		case TEKI_Dororo:
		{
			teki.spawnItems();
			break;
		}
		case TEKI_Miurin:
		{
			teki.createDeadEffect();
			break;
		}
		}

		teki.die();
		return true;
	}

	return false;
}

